1	// JSON Schema type checking and Python-flavoured equality helpers.
2	//
3	// jsonschema (Python) compares values with Python semantics, where
4	// True == 1 and False == 0. Its internal `unbool` helper rewrites
5	// booleans to 1/0 recursively before comparing. We mirror that here.
6	
7	export function isType(instance, type) {
8	  switch (type) {
9	    case 'array':
10	      return Array.isArray(instance);
11	    case 'boolean':
12	      return typeof instance === 'boolean';
13	    case 'integer':
14	      return typeof instance === 'number' && Number.isInteger(instance);
15	    case 'number':
16	      return typeof instance === 'number';
17	    case 'null':
18	      return instance === null;
19	    case 'object':
20	      return (
21	        typeof instance === 'object' && instance !== null && !Array.isArray(instance)
22	      );
23	    case 'string':
24	      return typeof instance === 'string';
25	    default:
26	      throw new Error(`Unknown type '${type}'`);
27	  }
28	}
29	
30	// Recursively rewrite true -> 1 and false -> 0 (jsonschema._utils.unbool).
31	export function unbool(value) {
32	  if (value === true) return 1;
33	  if (value === false) return 0;
34	  if (Array.isArray(value)) return value.map(unbool);
35	  if (typeof value === 'object' && value !== null) {
36	    const out = {};
37	    for (const [k, v] of Object.entries(value)) out[k] = unbool(v);
38	    return out;
39	  }
40	  return value;
41	}
42	
43	// Deep equality with Python semantics (after unbool-ing both sides).
44	export function deepEqual(one, two) {
45	  return plainEqual(unbool(one), unbool(two));
46	}
47	
48	function plainEqual(a, b) {
49	  if (a === b) return true;
50	  if (typeof a === 'number' && typeof b === 'number') return a === b;
51	  if (Array.isArray(a) && Array.isArray(b)) {
52	    if (a.length !== b.length) return false;
53	    for (let i = 0; i < a.length; i++) {
54	      if (!plainEqual(a[i], b[i])) return false;
55	    }
56	    return true;
57	  }
58	  if (isPlainObject(a) && isPlainObject(b)) {
59	    const ka = Object.keys(a);
60	    const kb = Object.keys(b);
61	    if (ka.length !== kb.length) return false;
62	    for (const k of ka) {
63	      if (!Object.prototype.hasOwnProperty.call(b, k)) return false;
64	      if (!plainEqual(a[k], b[k])) return false;
65	    }
66	    return true;
67	  }
68	  return false;
69	}
70	
71	function isPlainObject(v) {
72	  return typeof v === 'object' && v !== null && !Array.isArray(v);
73	}
74	
75	// Length of a string in Unicode code points (Python's len(str)).
76	export function codePointLength(str) {
77	  let n = 0;
78	  for (const _ of str) n++;
79	  return n;
80	}

1	// Error types mirroring jsonschema's ValidationError / SchemaError surface
2	// that the translated program relies on.
3	
4	export class ValidationError {
5	  constructor(message) {
6	    this.message = message;
7	    // Absolute path within the instance (filled in by the validator as the
8	    // error bubbles up through keyword validators).
9	    this.path = [];
10	    // Relative schema path (keyword chain), informational only.
11	    this.schemaPath = [];
12	    // Set by the validator loop as the error bubbles up:
13	    this.validator = undefined;
14	    this.validatorValue = undefined;
15	    this.instance = undefined;
16	    this.schema = undefined;
17	    // Sub-errors (e.g. for anyOf/oneOf), informational only.
18	    this.context = [];
19	  }
20	}
21	
22	export class SchemaError extends Error {
23	  constructor(message, errors = []) {
24	    super(message);
25	    this.name = 'SchemaError';
26	    this.errors = errors;
27	  }
28	}

