// String keywords: maxLength, minLength, pattern.
//
// Lengths are measured in Unicode code points (Python's len(str)), not
// UTF-16 code units, so astral-plane characters count as one.
// `pattern` follows Python's re.search semantics: the regex matches if it
// is found anywhere in the string (unanchored).

import { ValidationError } from '../errors.mjs';
import { codePointLength } from '../types.mjs';

export function* maxLength(validator, maxLengthValue, instance, schema) {
  if (!validator.isType(instance, 'string')) return;
  if (codePointLength(instance) > maxLengthValue) {
    yield new ValidationError(
      `${JSON.stringify(instance)} is too long`
    );
  }
}

export function* minLength(validator, minLengthValue, instance, schema) {
  if (!validator.isType(instance, 'string')) return;
  if (codePointLength(instance) < minLengthValue) {
    yield new ValidationError(
      `${JSON.stringify(instance)} is too short`
    );
  }
}

export function* pattern(validator, patternValue, instance, schema) {
  if (!validator.isType(instance, 'string')) return;
  const re = new RegExp(patternValue, 'u');
  if (!re.test(instance)) {
    yield new ValidationError(
      `${JSON.stringify(instance)} does not match ${JSON.stringify(patternValue)}`
    );
  }
}
